fn exact(x: f64) -> String { format!("{:.60}", x) }

fn main() {
    // ---------- exact binary values ----------
    for lit in [0.45f32, 0.67, 0.33, 0.12345, 0.25, 0.5, 0.75] {
        println!("f32 literal {:?} -> exact = {}", lit, exact(lit as f64));
    }
    println!();
    for lit in [0.45f64, 0.67, 0.33, 0.12345, 0.25, 0.5, 0.75] {
        println!("f64 literal {:?} -> exact = {}", lit, exact(lit));
    }
    println!();

    // ---------- THE DISCRIMINATOR: 0.12345 at precisions 1..5 ----------
    println!("=== lines 20-24: Format::percentage(0.12345f, i) for i=1..5 ===");
    let v32: f32 = 0.12345;
    for p in 1..=5usize {
        // A: widen f32 -> f64, multiply in f64  (lead's hypothesis)
        let a = (v32 as f64) * 100.0;
        // B: multiply in f32, then widen for printing
        let b = (v32 * 100.0f32) as f64;
        // C: value parsed/stored as f64 from decimal literal
        let c = 0.12345f64 * 100.0;
        // D: f32 stored, printed as f32 with precision (Rust f32 Display)
        let d = v32 * 100.0f32;
        println!("p={} A(f32->f64 *100)={:.*}  B(f32*100f32)={:.*}  C(f64 *100)={:.*}  D(f32 fmt)={:.*}",
                 p, p, a, p, b, p, c, p, d);
    }
    println!();
    println!("exact A = {}", exact((v32 as f64) * 100.0));
    println!("exact B = {}", exact((v32 * 100.0f32) as f64));
    println!("exact C = {}", exact(0.12345f64 * 100.0));
    println!("f32 bits of 0.12345f32*100.0f32 = {:#x} value={:?}", (v32*100.0f32).to_bits(), v32*100.0f32);
    println!();

    // ---------- other percentage lines ----------
    println!("=== line 3/5: Percentage(0.45f,1) ===");
    println!("  A={:.1} B={:.1} C={:.1}", (0.45f32 as f64)*100.0, ((0.45f32*100.0f32) as f64), 0.45f64*100.0);
    println!("=== line 4: Percentage(0.67f,2) ===");
    println!("  A={:.2} B={:.2} C={:.2}", (0.67f32 as f64)*100.0, ((0.67f32*100.0f32) as f64), 0.67f64*100.0);
    println!("=== line 11: Format::percentage(0.33f) default prec ===");
    for p in 0..=6 { println!("  prec {} -> A={:.*}", p, p, (0.33f32 as f64)*100.0); }
    println!("=== lines 33/34/35: Percentage(0.25f,1)/(0.5f,2)/(0.75f,3) ===");
    println!("  {:.1} {:.2} {:.3}", (0.25f32 as f64)*100.0, (0.5f32 as f64)*100.0, (0.75f32 as f64)*100.0);
    println!();

    // ---------- integer-derived ratios ----------
    println!("=== integer ratio call sites ===");
    let cases: [(i64,i64,usize,&str);9] = [
        (45,90,1,"line1/2 bar suffix, line8 builder"),
        (33,100,1,"line11? no -> line13 bar suffix"),
        (1,3,1,"line10 tracker pct 33.3%"),
        (30,100,1,"line14 bar suffix"),
        (60,100,1,"line15 bar suffix"),
        (50,100,1,"line16 display + lines 25-29 bar suffix"),
        (75,100,1,"line17 display"),
        (2,10,1,"line18 cyclic 20.0%"),
        (3,10,1,"line19 task 30.0%"),
    ];
    for (c,t,p,tag) in cases {
        let r64 = c as f64 / t as f64;
        let r32 = c as f32 / t as f32;
        println!("  {}/{} p={}  f64:{:.*}  f32widen:{:.*}  f32mul:{:.*}   [{}]",
            c,t,p, p, r64*100.0, p, (r32 as f64)*100.0, p, (r32*100.0f32) as f64, tag);
    }
    println!();

    // ---------- filled cell counts ----------
    println!("=== filled = (int)(ratio*W) ===");
    for (c,t,w) in [(45i64,90i64,40usize),(33,100,25),(30,100,50),(60,100,50),
                    (50,100,10),(50,100,20),(50,100,30),(50,100,40),(50,100,50)] {
        let r64 = c as f64 / t as f64;
        let r32 = c as f32 / t as f32;
        println!("  {}/{} W={}: f64 -> {} (exact {}), f32 -> {} (exact {})",
            c,t,w, (r64 * w as f64) as i64, exact(r64 * w as f64),
            (r32 * w as f32) as i64, exact((r32 * w as f32) as f64));
    }
    println!();

    // ---------- tie / round-half-even behaviour of Rust ----------
    println!("=== Rust rounding of exact halves ===");
    println!("  {{:.0}} 0.5 -> {:.0}   1.5 -> {:.0}   2.5 -> {:.0}   3.5 -> {:.0}", 0.5f64,1.5f64,2.5f64,3.5f64);
    println!("  {{:.1}} 0.25 -> {:.1}  0.75 -> {:.1}  0.125 -> {:.2}  0.375 -> {:.2}", 0.25f64,0.75f64,0.125f64,0.375f64);
    println!("  {{:.2}} 12.345 (f64 literal) -> {:.2}  exact={}", 12.345f64, exact(12.345f64));
}
EOF
