#include <cstdio>
#include <iostream>
#include <sstream>
#include <iomanip>
#include <string>

static std::string oss_fixed(double v, int p) {
    std::ostringstream o; o << std::fixed << std::setprecision(p) << v; return o.str();
}
static std::string oss_fixed_f(float v, int p) {   // float inserted directly
    std::ostringstream o; o << std::fixed << std::setprecision(p) << v; return o.str();
}
static std::string pf(double v, int p) { char b[128]; snprintf(b,sizeof b,"%.*f",p,v); return b; }

int main(){
    printf("=== 0.12345f at precisions 1..5, ALL candidate paths ===\n");
    float v = 0.12345f;
    for (int p=1;p<=5;++p){
        double A = (double)v * 100.0;      // widen then f64 multiply
        float  Bf = v * 100.0f;            // f32 multiply
        double C = 0.12345 * 100.0;        // f64 literal * 100
        double D = 12.345;                 // literal
        printf("p=%d  A=%s  B=%s  Bfloat<<=%s  C=%s  D=%s  printfA=%s\n", p,
               oss_fixed(A,p).c_str(), oss_fixed((double)Bf,p).c_str(), oss_fixed_f(Bf,p).c_str(),
               oss_fixed(C,p).c_str(), oss_fixed(D,p).c_str(), pf(A,p).c_str());
    }
    printf("exact A = %.60f\n", (double)v*100.0);
    printf("exact B = %.60f\n", (double)(v*100.0f));
    printf("exact C = %.60f\n", 0.12345*100.0);
    printf("\n=== other percentage sites ===\n");
    printf("0.45f p1: dbl=%s f32mul=%s f64lit=%s\n", oss_fixed((double)0.45f*100.0,1).c_str(), oss_fixed((double)(0.45f*100.0f),1).c_str(), oss_fixed(0.45*100.0,1).c_str());
    printf("0.67f p2: dbl=%s f32mul=%s f64lit=%s\n", oss_fixed((double)0.67f*100.0,2).c_str(), oss_fixed((double)(0.67f*100.0f),2).c_str(), oss_fixed(0.67*100.0,2).c_str());
    printf("0.33f p1: dbl=%s ; default-precision(no fixed/setprec, 6) would be: ", oss_fixed((double)0.33f*100.0,1).c_str());
    { std::ostringstream o; o << (double)0.33f*100.0; printf("%s\n", o.str().c_str()); }
    { std::ostringstream o; o << std::fixed << (double)0.33f*100.0; printf("0.33f fixed w/ DEFAULT precision(6): %s\n", o.str().c_str()); }
    printf("0.25f p1=%s  0.5f p2=%s  0.75f p3=%s\n", oss_fixed((double)0.25f*100.0,1).c_str(), oss_fixed((double)0.5f*100.0,2).c_str(), oss_fixed((double)0.75f*100.0,3).c_str());

    printf("\n=== integer ratios (f64) ===\n");
    int cs[9][2]={{45,90},{33,100},{1,3},{30,100},{60,100},{50,100},{75,100},{2,10},{3,10}};
    for(auto&c:cs){
      double r=(double)c[0]/c[1]; float rf=(float)c[0]/c[1];
      printf("  %d/%d -> f64:%s f32:%s\n",c[0],c[1],oss_fixed(r*100.0,1).c_str(),oss_fixed((double)(rf*100.0f),1).c_str());
    }

    printf("\n=== tie rounding: ostringstream vs printf ===\n");
    double halves[]={0.5,1.5,2.5,3.5};
    for(double h:halves) printf("  %.1f -> oss:%s printf:%s\n",h,oss_fixed(h,0).c_str(),pf(h,0).c_str());
    printf("  0.25@1 -> oss:%s printf:%s\n",oss_fixed(0.25,1).c_str(),pf(0.25,1).c_str());
    printf("  0.75@1 -> oss:%s printf:%s\n",oss_fixed(0.75,1).c_str(),pf(0.75,1).c_str());
    printf("  0.125@2 -> oss:%s printf:%s\n",oss_fixed(0.125,2).c_str(),pf(0.125,2).c_str());
    printf("  0.375@2 -> oss:%s printf:%s\n",oss_fixed(0.375,2).c_str(),pf(0.375,2).c_str());
    return 0;
}
